1	// Package indexroom implements chain ingestion with optional block
2	// timestamps, reorg handling, consistent paginated transaction queries, and
3	// time-bucketed transaction statistics over the main chain.
4	package indexroom
5	
6	import (
7		"fmt"
8		"sync"
9		"unicode/utf8"
10	)
11	
12	// Block is one ingested block with its transactions.
13	//
14	// Time is the optional block timestamp as non-negative Unix seconds. A nil
15	// pointer means the block carries no timestamp and is distinct from a
16	// timestamp of zero. Append and Reorg reject negative values; stored blocks
17	// keep their own copy, so mutating the pointer or its target after a call
18	// never affects the index. Block timestamps need not be monotonic: equal
19	// values and values that decrease with height are both accepted.
20	type Block struct {
21		Height int64
22		// Hash, Parent, and every Txs identifier must be valid UTF-8; Append and
23		// Reorg reject a block carrying invalid bytes rather than letting a
24		// snapshot export silently rewrite them to U+FFFD. Txs keeps empty and
25		// duplicated identifiers, order, case, and surrounding whitespace
26		// exactly as given.
27		Hash   string
28		Parent string
29		Txs    []string
30		Time   *int64
31	}
32	
33	// Index is the durable chain view.
34	//
35	// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
36	// concurrent use; the exported fields are meant for read-only inspection
37	// after all calls have finished.
38	type Index struct {
39		Blocks map[int64]Block
40		ByHash map[string]int64
41		Tip    int64
42	
43		mu  sync.Mutex
44		key [32]byte
45	}
46	
47	// New returns an empty index.
48	func New() *Index {
49		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
50	}
51	
52	// Append accepts a block only when it extends the current tip, keeping the
53	// chain linear. Re-submitting a block identical to one already on the main
54	// chain is a successful no-op. A block whose hash, parent, or any transaction
55	// identifier carries invalid UTF-8 is rejected with an error naming the
56	// height and field (and the zero-based tx position); a rejected append leaves
57	// the index untouched.
58	func (index *Index) Append(block Block) error {
59		index.mu.Lock()
60		defer index.mu.Unlock()
61		return index.appendLocked(block)
62	}
63	
64	func (index *Index) appendLocked(block Block) error {
65		if err := validateBlockEncoding(block); err != nil {
66			return err
67		}
68		if block.Hash == "" {
69			return errInvalid("block needs a hash")
70		}
71		if block.Time != nil && *block.Time < 0 {
72			return errInvalid("block time must not be negative")
73		}
74		if index.Tip == 0 {
75			// Empty index: only the first block at height 1 is accepted; its
76			// parent becomes the chain start identifier and need not be indexed.
77			if block.Height != 1 {
78				return errInvalid("first block must be at height 1")
79			}
80			index.storeLocked(block)
81			return nil
82		}
83		if old, exists := index.Blocks[block.Height]; exists {
84			if sameBlock(old, block) {
85				return nil
86			}
87			return errInvalid("height already indexed with different content")
88		}
89		if block.Height != index.Tip+1 {
90			return errInvalid("block height must extend the current tip")
91		}
92		if block.Parent != index.Blocks[index.Tip].Hash {
93			return errInvalid("parent does not match the current tip")
94		}
95		if _, exists := index.ByHash[block.Hash]; exists {
96			return errInvalid("hash already indexed at another height")
97		}
98		index.storeLocked(block)
99		return nil
100	}
101	
102	// Reorg replaces the tip range with an alternate branch and reports the
103	// dropped old heights in ascending order. The branch is validated in full
104	// before anything is applied — including UTF-8 validity of every block's
105	// hash, parent, and transaction identifiers, even in the last block — so a
106	// rejected reorg leaves the index exactly as it was and reports no dropped
107	// heights. Heights whose old block is identical to the new one are not
108	// reported; re-submitting the branch already in effect returns an empty list.
109	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
110		index.mu.Lock()
111		defer index.mu.Unlock()
112	
113		if len(blocks) == 0 {
114			return nil, errInvalid("empty branch")
115		}
116		// Every identifier must be valid UTF-8 before any lookup or mutation.
117		// The first block's parent need not be indexed, but it still has to be
118		// encodable, and an error in the last block must reject the whole branch.
119		for _, block := range blocks {
120			if err := validateBlockEncoding(block); err != nil {
121				return nil, err
122			}
123		}
124		ancestor, ok := index.ByHash[blocks[0].Parent]
125		if !ok {
126			return nil, errInvalid("branch parent is unknown")
127		}
128		if blocks[0].Height != ancestor+1 {
129			return nil, errInvalid("branch must start at the ancestor height plus one")
130		}
131		seen := make(map[string]bool, len(blocks))
132		for i, block := range blocks {
133			if block.Hash == "" {
134				return nil, errInvalid("block needs a hash")
135			}
136			if block.Time != nil && *block.Time < 0 {
137				return nil, errInvalid("block time must not be negative")
138			}
139			if seen[block.Hash] {
140				return nil, errInvalid("duplicate hash inside branch")
141			}
142			seen[block.Hash] = true
143			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
144				return nil, errInvalid("hash conflicts with a retained block")
145			}
146			if i > 0 {
147				prev := blocks[i-1]
148				if block.Height != prev.Height+1 {
149					return nil, errInvalid("branch heights must be consecutive")
150				}
151				if block.Parent != prev.Hash {
152					return nil, errInvalid("branch parent does not match the previous block")
153				}
154			}
155		}
156	
157		// Everything validated; compute the dropped heights before mutating.
158		newTip := blocks[len(blocks)-1].Height
159		dropped := []int64{}
160		for height := ancestor + 1; height <= index.Tip; height++ {
161			if height > newTip {
162				dropped = append(dropped, height)
163				continue
164			}
165			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
166				dropped = append(dropped, height)
167			}
168		}
169		for height := ancestor + 1; height <= index.Tip; height++ {
170			delete(index.ByHash, index.Blocks[height].Hash)
171			delete(index.Blocks, height)
172		}
173		index.Tip = ancestor
174		for _, block := range blocks {
175			index.storeLocked(block)
176		}
177		return dropped, nil
178	}
179	
180	// storeLocked records a validated block, copying its transactions and
181	// timestamp so later caller-side mutation cannot alter the stored block.
182	func (index *Index) storeLocked(block Block) {
183		if block.Txs != nil {
184			txs := make([]string, len(block.Txs))
185			copy(txs, block.Txs)
186			block.Txs = txs
187		}
188		if block.Time != nil {
189			t := *block.Time
190			block.Time = &t
191		}
192		index.Blocks[block.Height] = block
193		index.ByHash[block.Hash] = block.Height
194		index.Tip = block.Height
195	}
196	
197	// validateBlockEncoding rejects a block whose hash, parent, or any
198	// transaction identifier contains invalid UTF-8 bytes. JSON snapshots can
199	// only carry valid UTF-8 — the encoder would silently rewrite bad bytes to
200	// U+FFFD, merging distinct identifiers after a restore — so such a block can
201	// never enter the index. The error names the block height and the field; a
202	// bad transaction identifier also names its zero-based position. A genuine
203	// U+FFFD is valid UTF-8 and is never rejected by this check.
204	func validateBlockEncoding(block Block) error {
205		if !utf8.ValidString(block.Hash) {
206			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "hash"))
207		}
208		if !utf8.ValidString(block.Parent) {
209			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "parent"))
210		}
211		for position, tx := range block.Txs {
212			if !utf8.ValidString(tx) {
213				return errInvalid(fmt.Sprintf("block at height %d: field %q element %d contains invalid UTF-8 bytes", block.Height, "txs", position))
214			}
215		}
216		return nil
217	}
218	
219	// sameBlock reports whether two blocks are identical: same height, hash,
220	// parent, transactions in order, and timestamp presence and value. An empty
221	// tx list equals a missing one, but a missing timestamp never equals zero.
222	func sameBlock(a, b Block) bool {
223		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
224			return false
225		}
226		if len(a.Txs) != len(b.Txs) {
227			return false
228		}
229		for i := range a.Txs {
230			if a.Txs[i] != b.Txs[i] {
231				return false
232			}
233		}
234		if (a.Time == nil) != (b.Time == nil) {
235			return false
236		}
237		return a.Time == nil || *a.Time == *b.Time
238	}
239	
240	type errInvalid string
241	
242	func (e errInvalid) Error() string { return string(e) }
243

