18	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
19	// size, a malformed cursor, a cursor issued by another index instance, or
20	// continuation conditions that differ from the first page. It never reports
21	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
22	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
23	
24	// ErrQueryChanged marks a continuation whose pinned range no longer matches
25	// the first page: a block in the range was replaced (even under the same
26	// hash, and even if only its timestamp changed) or the chain was shortened
27	// below the pinned upper bound. No results are returned; the caller must
28	// restart from a first-page query.
29	var ErrQueryChanged = errors.New("indexroom: query data changed")
30	
31	const (
32		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
33		DefaultPageSize = 100
34		// MaxPageSize is the largest accepted TxQuery.PageSize.
35		MaxPageSize = 1000
36	)
37	
38	// TxQuery describes a transaction lookup against the main chain.
39	type TxQuery struct {
40		// From and To bound the searched heights, both inclusive. A zero From
41		// starts at height 1. A zero To pins the chain tip seen by the first
42		// page; an explicit To above the tip is clamped to it. Explicit heights
43		// must be positive, and an explicit To must not be below From.
44		From int64
45		To   int64
46		// TxIDs restricts results to these identifiers, matched by exact string
47		// comparison; an empty slice disables the filter. Duplicates and order
48		// inside the slice are irrelevant.
49		TxIDs []string
50		// PageSize picks the page length, 1..MaxPageSize; zero means
51		// DefaultPageSize. It may change between pages of the same query.
52		PageSize int
53		// Cursor continues an earlier query; empty asks for the first page. On
54		// continuation the height range and TxIDs must equal the first page's.
55		Cursor string
56	}
57	
58	// TxHit is one transaction occurrence on the main chain. The same
59	// identifier appears once per occurrence, in different blocks or several
60	// times inside one block.
61	type TxHit struct {
62		Height    int64
63		BlockHash string
64		TxID      string
65		Position  int
66	}
67	
68	// TxPage is one page of query results together with statistics over the
69	// whole filtered range. Hits are ordered by height, then by position inside
70	// the block.
71	type TxPage struct {
72		Hits []TxHit
73		// TotalMatches counts every matching occurrence in the pinned range; it
74		// does not change between pages of the same query.
75		TotalMatches int64
76		// MatchedBlocks counts the blocks holding at least one match.
77		MatchedBlocks int64
78		// ToHeight is the upper bound pinned by the first page: the requested
79		// To clamped to the chain tip seen at that moment.
80		ToHeight int64
81		// NextCursor continues the query; empty means this is the last page.
82		NextCursor string
83	}
84	
85	// QueryTxs searches the main chain for transaction occurrences matching the
86	// query. Every call observes one complete chain state: concurrent Append or
87	// Reorg calls never leak into a page, and the returned records are copies
88	// the caller may freely mutate. The query itself never modifies the index.
89	//
90	// The first page (empty Cursor) pins the filtered range and returns a
91	// continuation cursor while more results remain. Continuations reuse the
92	// pinned range — blocks appended above it are invisible to the query — and
93	// succeed as long as every block inside the range still matches the first
94	// page; otherwise they fail with ErrQueryChanged.
95	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
96		pageSize, err := normalizePageSize(query.PageSize)
97		if err != nil {
98			return TxPage{}, err
99		}
100		if query.Cursor != "" {
101			return index.continueQuery(query, pageSize)
102		}
103		return index.firstQuery(query, pageSize)
104	}
105	
106	func normalizePageSize(size int) (int, error) {
107		if size == 0 {
108			return DefaultPageSize, nil
109		}
110		if size < 0 || size > MaxPageSize {
111			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
112		}
113		return size, nil
114	}
115	
116	// normalizeRange validates the requested heights and resolves the zero From
117	// default. A zero To is left as-is; it is resolved against the chain tip
118	// while holding the lock.
119	func normalizeRange(from, to int64) (int64, int64, error) {
120		if from < 0 {
121			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
122		}
123		if to < 0 {
124			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
125		}
126		if from == 0 {
127			from = 1
128		}
129		if to != 0 && to < from {
130			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
131		}
132		return from, to, nil
133	}
134	
135	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
136		from, to, err := normalizeRange(query.From, query.To)
137		if err != nil {
138			return TxPage{}, err
139		}
140	
141		index.mu.Lock()
142		defer index.mu.Unlock()
143	
144		if to == 0 || to > index.Tip {
145			to = index.Tip
146		}
147		page := TxPage{Hits: []TxHit{}, ToHeight: to}
148		if from > to {
149			// Empty index or a start above the tip: a successful empty result.
150			return page, nil
151		}
152		hits, blocks := index.collectLocked(from, to, query.TxIDs)
153		return index.makePageLocked(query, from, to, hits, blocks, 0, pageSize), nil
154	}
155	
156	func (index *Index) continueQuery(query TxQuery, pageSize int) (TxPage, error) {
157		payload, err := index.decodeCursor(query.Cursor)
158		if err != nil {
159			return TxPage{}, err
160		}
161		from, _, err := normalizeRange(query.From, query.To)
162		if err != nil {
163			return TxPage{}, err
164		}
165		if from != payload.From {
166			return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
167		}
168		if query.To != payload.ReqTo {
169			return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
170		}
171		if got := hex.EncodeToString(hashTxSet(query.TxIDs)); got != payload.Set {
172			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
173		}
174	
175		index.mu.Lock()
176		defer index.mu.Unlock()
177	
178		if index.Tip < payload.To {
179			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
180				ErrQueryChanged, index.Tip, payload.To)
181		}
182		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
183			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
184		}
185		hits, blocks := index.collectLocked(payload.From, payload.To, query.TxIDs)
186		if payload.Off > int64(len(hits)) {
187			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
188		}
189		return index.makePageLocked(query, payload.From, payload.To, hits, blocks, payload.Off, pageSize), nil
190	}
191	
192	// makePageLocked slices one page out of the full match list and mints the
193	// continuation cursor when matches remain. The caller must hold index.mu.
194	func (index *Index) makePageLocked(query TxQuery, from, to int64, hits []TxHit, blocks int64, offset int64, pageSize int) TxPage {
195		page := TxPage{
196			TotalMatches:  int64(len(hits)),
197			MatchedBlocks: blocks,
198			ToHeight:      to,
199		}
200		rest := hits[int(offset):]
201		end := pageSize
202		if end > len(rest) {
203			end = len(rest)
204		}
205		page.Hits = append([]TxHit{}, rest[:end]...)
206		if end < len(rest) {
207			page.NextCursor = index.encodeCursor(cursorPayload{
208				V:     1,
209				From:  from,
