	err error
}

// startExport launches an export to w in the background.
func startExport(index *Index, w io.Writer) chan exportResult {
	done := make(chan exportResult, 1)
	go func() {
		var buf bytes.Buffer
		err := index.Export(w)
		done <- exportResult{raw: buf.String(), err: err}
	}()
	return done
