		Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "", "t1"}},
		Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t2"}, Time: intptr(0)},
		Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"t3", "t3"}, Time: intptr(1700000000)},
	)
}

