		t.Fatalf("restored hits=%v, want %v", oldPage.Hits, wantOld)
	}
	gonePage, err := index.QueryTxs(TxQuery{TxIDs: []string{"t2", "t3"}})
	if err != nil {
		t.Fatal(err)
	}
	if gonePage.TotalMatches != 0 {
		t.Fatalf("reorged-away transactions still visible: %+v", gonePage)
	}
