	if err != nil {
		t.Fatal(err)
	}
	wantNew := []TxHit{
		{Height: 2, BlockHash: "h2b", TxID: "n2", Position: 0},
		{Height: 2, BlockHash: "h2b", TxID: "n2", Position: 2},
	}
	if !reflect.DeepEqual(newPage.Hits, wantNew) {
		t.Fatalf("post-reorg hits=%v, want %v", newPage.Hits, wantNew)
	}
